import{_ as e,c as s,o as t,aj as a}from"./chunks/framework.Id7s26SP.js";const k=JSON.parse('{"title":"One App, Several Clients","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/multi-client.md","filePath":"getting-started/multi-client.md"}'),n={name:"getting-started/multi-client.md"};function o(h,i,l,p,d,r){return t(),s("div",null,[...i[0]||(i[0]=[a(`<h1 id="one-app-several-clients" tabindex="-1">One App, Several Clients <a class="header-anchor" href="#one-app-several-clients" aria-label="Permalink to “One App, Several Clients”">​</a></h1><p>Your web and iOS clients can share one Primitive app: the same app ID, environments, server configuration, and model schema. Each client has its own UI, dependencies, and build.</p><p><code>primitive init</code> — the command the <a href="./template-app.html">Quick Start</a>&#39;s <code>npx create-primitive-app</code> runs on your behalf — scaffolds that repository for you, and the layout it produces is the one this page describes.</p><h2 id="scaffolding-both-clients" tabindex="-1">Scaffolding both clients <a class="header-anchor" href="#scaffolding-both-clients" aria-label="Permalink to “Scaffolding both clients”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --platform</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web,ios</span></span></code></pre></div><p><code>--platform</code> takes one platform or a comma-separated list; run it interactively and the prompt lets you select both. One run creates the app, downloads both templates, and produces:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>my-app/</span></span>
<span class="line"><span>  primitive/config.json           # the environments: backend URL + app ID per environment</span></span>
<span class="line"><span>  primitive/&lt;env&gt;/                # your app&#39;s server configuration, as TOML</span></span>
<span class="line"><span>  models/models.toml              # the model schema — one copy, shared</span></span>
<span class="line"><span>  AGENTS.md                       # what this repo is and what is shared</span></span>
<span class="line"><span>  web/                            # the Vue client: its own package.json, .env, AGENTS.md</span></span>
<span class="line"><span>  ios/                            # the SwiftUI client: its own project, AGENTS.md</span></span></code></pre></div><p>There is one git repository, at the root, with one initial commit. There is no root <code>package.json</code> and no workspace file: the clients are independent projects sitting side by side, each with its own dependencies, build, tests and deploy. What they share sits above them.</p><p>A single-platform <code>primitive init my-app</code> creates the client at the repository root.</p><h2 id="adding-a-client-later" tabindex="-1">Adding a client later <a class="header-anchor" href="#adding-a-client-later" aria-label="Permalink to “Adding a client later”">​</a></h2><p>You do not have to decide up front. Run init from inside the repository, pointing at the new client&#39;s directory:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ios</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --platform</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ios</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # or just \`primitive init --platform ios\`</span></span></code></pre></div><p>The new client uses the app and environment from your project’s <code>primitive/config.json</code>. Review the new files with <code>git status</code>, then commit them in the existing repository.</p><p>If your repository is a single client at the root, adding a second one moves the model schema up to <code>my-app/models/models.toml</code> and rewires the existing client to read it there, after asking you. Nothing else about that client moves: its <code>package.json</code>, sources and build config stay exactly where they are.</p><p>For CI and scripted setup, <code>.primitive-init.toml</code>:</p><div class="language-toml"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">action = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;add-client&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">platform = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ios&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">promote_schema = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # consent to move a single-client repo&#39;s schema to the root</span></span></code></pre></div><h2 id="what-is-shared-and-what-is-not" tabindex="-1">What is shared and what is not <a class="header-anchor" href="#what-is-shared-and-what-is-not" aria-label="Permalink to “What is shared and what is not”">​</a></h2><table tabindex="0"><thead><tr><th>Per app — at the repository root</th><th>Per client — in its own directory</th></tr></thead><tbody><tr><td>Environments and the app ID (<code>primitive/config.json</code>)</td><td>Generated code (models, function invokers)</td></tr><tr><td>Server configuration (<code>primitive/&lt;env&gt;/</code>)</td><td>Runtime connection settings</td></tr><tr><td>The model schema (<code>models/models.toml</code>)</td><td>Dependencies, build and test configuration</td></tr><tr><td>App secrets and config vars</td><td>Deploy configuration</td></tr><tr><td>The app-wide <code>AGENTS.md</code></td><td>The client&#39;s own <code>AGENTS.md</code></td></tr></tbody></table><p>Server configuration is shared. Each client generates its own model code and function invokers in its own language. <code>config push</code> writes database-type declarations for server functions into the shared configuration tree.</p><h2 id="the-model-schema" tabindex="-1">The model schema <a class="header-anchor" href="#the-model-schema" aria-label="Permalink to “The model schema”">​</a></h2><p>Keep one <code>models/models.toml</code> so every client uses the same field names.</p><p>Each client points at that one file:</p><ul><li>The web client uses the shared file for code generation and runtime model definitions.</li><li>The Swift client points to it through <code>bao-codegen.json</code>.</li></ul><p>A client&#39;s template ships code generated from its own starter models, so adding a client adds any of those models the schema does not already declare, and says which ones. Models you already have keep their definitions exactly as they are.</p><p>To change a model: edit <code>models/models.toml</code>, then run each client&#39;s codegen (<code>pnpm codegen</code> in the web client, <code>bash scripts/codegen.sh</code> in the Swift one). See <a href="./choosing-your-data-model.html">Choosing Your Data Model</a> for what belongs in the schema in the first place.</p><h2 id="running-commands" tabindex="-1">Running commands <a class="header-anchor" href="#running-commands" aria-label="Permalink to “Running commands”">​</a></h2><p>Run CLI commands from the root or either client directory. The CLI finds the nearest <code>primitive/config.json</code>, so each location uses the same project and selected environment.</p><h2 id="environments" tabindex="-1">Environments <a class="header-anchor" href="#environments" aria-label="Permalink to “Environments”">​</a></h2><p>An environment is a backend and an app together, and it belongs to the app rather than to one client:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> use</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> staging</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # every command in this repository now targets staging</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">primitive</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # or name one per command</span></span></code></pre></div><p><code>primitive env use</code> writes this machine&#39;s selection, not a tracked file, so it is yours and not your teammates&#39;. Each client resolves its own runtime connection settings from that same project config, so pointing the repository at an environment points both clients at the same backend and app.</p><h2 id="one-sign-in-link-for-both-clients" tabindex="-1">One sign-in link for both clients <a class="header-anchor" href="#one-sign-in-link-for-both-clients" aria-label="Permalink to “One sign-in link for both clients”">​</a></h2><p>Use one HTTPS sign-in link for both clients. A universal link opens the installed iOS app; otherwise it opens the web sign-in page.</p><p>The environment carries the web origin, alongside the backend URL and app ID it already holds:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;environments&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;dev&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:  { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;apiUrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://localhost:8787&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;appId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;app_…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;webUrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://localhost:5173&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;prod&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;apiUrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://primitiveapi.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;appId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;app_…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;webUrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://app.example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>See <a href="./authentication.html#ios-web-one-https-link">Authentication</a> for the <code>webUrl</code> format, what <code>primitive init</code> seeds automatically, and the deploy-time rollout (association file, then the <code>applinks:</code> entitlement).</p><h2 id="agents-md" tabindex="-1">AGENTS.md <a class="header-anchor" href="#agents-md" aria-label="Permalink to “AGENTS.md”">​</a></h2><p>The root <code>AGENTS.md</code> describes the app: the layout, what is shared, where the schema is. Each client keeps its own, describing its stack and conventions, and it ships with that client&#39;s template — so app-wide facts belong in the root file, which upgrades never touch.</p>`,38)])])}const g=e(n,[["render",o]]);export{k as __pageData,g as default};
